import re
from collections import OrderedDict, deque
from typing import Dict, List, Tuple, Any


_SECTION_RE = re.compile(r"^\[(.+?)\]\s*$")
_CHOICE_RE = re.compile(r"^\s*(\d+)\.\s*(.*?)\s*$")


def _split_arrow(line: str) -> Tuple[str, str]:
    if "->" not in line:
        raise ValueError(f"Missing '->' in line: {line!r}")
    left, right = line.rsplit("->", 1)
    return left.strip(), right.strip()


def _parse_sections(text: str) -> "OrderedDict[str, List[str]]":
    sections: "OrderedDict[str, List[str]]" = OrderedDict()
    current: str | None = None

    for raw in text.replace("\r\n", "\n").replace("\r", "\n").split("\n"):
        line = raw.strip("\n")
        s = line.strip()
        if not s:
            continue

        m = _SECTION_RE.match(s)
        if m:
            current = m.group(1).strip()
            if not current:
                raise ValueError("Empty section header [] is not allowed")
            if current in sections:
                raise ValueError(f"Duplicate section id: {current}")
            sections[current] = []
            continue

        if current is None:
            raise ValueError(f"Content before first section header: {line!r}")

        sections[current].append(s)

    if not sections:
        raise ValueError("No sections found")

    for sec, lines in sections.items():
        if not lines:
            raise ValueError(f"Section {sec!r} is empty")

    return sections


def parse_script(text: str) -> Dict[str, Any]:
    """Parse dialogue script text into a graph.

    Returns:
        {"nodes": [...], "edges": [...]} with node dicts containing
        id/text/speaker/type and edge dicts containing from/to/text.
    """

    sections = _parse_sections(text)

    nodes: List[Dict[str, str]] = []
    edges: List[Dict[str, str]] = []

    for sec_id, lines in sections.items():
        if len(lines) == 1 and not _CHOICE_RE.match(_split_arrow(lines[0])[0]):
            left, target = _split_arrow(lines[0])
            if ":" not in left:
                raise ValueError(f"Line node missing speaker ':' in section {sec_id!r}: {lines[0]!r}")
            speaker, txt = left.split(":", 1)
            speaker = speaker.strip()
            txt = txt.strip()
            nodes.append({"id": sec_id, "text": txt, "speaker": speaker, "type": "line"})
            edges.append({"from": sec_id, "to": target, "text": ""})
        else:
            # Choice node: all lines should be numbered choices.
            nodes.append({"id": sec_id, "text": "", "speaker": "", "type": "choice"})
            for raw in lines:
                left, target = _split_arrow(raw)
                m = _CHOICE_RE.match(left)
                if not m:
                    raise ValueError(f"Invalid choice line in section {sec_id!r}: {raw!r}")
                choice_text = m.group(2).strip()
                edges.append({"from": sec_id, "to": target, "text": choice_text})

    # Materialize terminal End if referenced but not defined.
    node_ids = {n["id"] for n in nodes}
    targets = {e["to"] for e in edges}
    if "End" in targets and "End" not in node_ids:
        nodes.append({"id": "End", "text": "", "speaker": "", "type": "line"})
        node_ids.add("End")

    graph = {"nodes": nodes, "edges": edges}
    _validate_graph(graph, start_id=next(iter(sections.keys())))
    return graph


def _validate_graph(graph: Dict[str, Any], start_id: str) -> None:
    if not isinstance(graph, dict):
        raise ValueError("Graph must be a dict")
    nodes = graph.get("nodes")
    edges = graph.get("edges")
    if not isinstance(nodes, list) or not isinstance(edges, list):
        raise ValueError("Graph must have 'nodes' and 'edges' lists")

    node_by_id: Dict[str, Dict[str, str]] = {}
    for n in nodes:
        if not isinstance(n, dict):
            raise ValueError("Each node must be a dict")
        for k in ("id", "text", "speaker", "type"):
            if k not in n:
                raise ValueError(f"Node missing key {k!r}: {n}")
        nid = n["id"]
        if nid in node_by_id:
            raise ValueError(f"Duplicate node id: {nid}")
        node_by_id[nid] = n

    for e in edges:
        if not isinstance(e, dict):
            raise ValueError("Each edge must be a dict")
        for k in ("from", "to", "text"):
            if k not in e:
                raise ValueError(f"Edge missing key {k!r}: {e}")
        if e["from"] not in node_by_id:
            raise ValueError(f"Edge 'from' references missing node: {e}")
        if e["to"] not in node_by_id:
            raise ValueError(f"Edge 'to' references missing node: {e}")

    if start_id not in node_by_id:
        raise ValueError(f"Start node {start_id!r} not present")

    adj: Dict[str, List[str]] = {nid: [] for nid in node_by_id}
    for e in edges:
        adj[e["from"]].append(e["to"])

    seen = set([start_id])
    q = deque([start_id])
    while q:
        cur = q.popleft()
        for nxt in adj.get(cur, []):
            if nxt not in seen:
                seen.add(nxt)
                q.append(nxt)

    unreachable = [nid for nid in node_by_id if nid not in seen]
    if unreachable:
        raise ValueError(f"Unreachable nodes from {start_id!r}: {unreachable}")


def to_dot(graph: Dict[str, Any]) -> str:
    node_by_id = {n["id"]: n for n in graph["nodes"]}

    def esc(s: str) -> str:
        return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")

    lines: List[str] = ["digraph Dialogue {"]
    lines.append("  rankdir=LR;")

    for nid, n in node_by_id.items():
        if n["type"] == "line":
            label = (f"{n['speaker']}: {n['text']}" if n["speaker"] else n["text"]).strip() or nid
            shape = "box"
        else:
            label = nid
            shape = "diamond"
        lines.append(f"  \"{esc(nid)}\" [label=\"{esc(label)}\", shape={shape}];")

    for e in graph["edges"]:
        attrs = ""
        if e["text"]:
            attrs = f" [label=\"{esc(e['text'])}\"]"
        lines.append(f"  \"{esc(e['from'])}\" -> \"{esc(e['to'])}\"{attrs};")

    lines.append("}")
    return "\n".join(lines) + "\n"


def main() -> None:
    with open("/app/script.txt", "r", encoding="utf-8") as f:
        text = f.read()

    graph = parse_script(text)

    with open("/app/dialogue.json", "w", encoding="utf-8") as f:
        json.dump(graph, f, ensure_ascii=False, indent=2)
        f.write("\n")

    with open("/app/dialogue.dot", "w", encoding="utf-8") as f:
        f.write(to_dot(graph))


if __name__ == "__main__":
    main()
